<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ActiveUser;

final class ActiveUserUnitTest extends TestCase
{
    public function test_stores_all_properties(): void
    {
        $user = new ActiveUser(
            sessionId: 'sess-1',
            userId: 'user-abc',
            clientId: 'client-x',
            issuer: 'https://issuer.example.com',
            csid: 'csid-99',
            withMfa: true,
        );

        $this->assertSame('sess-1', $user->sessionId);
        $this->assertSame('user-abc', $user->userId);
        $this->assertSame('client-x', $user->clientId);
        $this->assertSame('https://issuer.example.com', $user->issuer);
        $this->assertSame('csid-99', $user->csid);
        $this->assertTrue($user->withMfa);
    }

    public function test_is_authenticated_when_user_id_not_empty(): void
    {
        $user = new ActiveUser('s', 'user-123', 'c', 'iss', 'csid', false);
        $this->assertTrue($user->isAuthenticated());
    }

    public function test_not_authenticated_when_user_id_empty(): void
    {
        $user = new ActiveUser('s', '', 'c', 'iss', 'csid', false);
        $this->assertFalse($user->isAuthenticated());
    }
}
